package com.acis.terain_photo.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.nio.file.*;import java.util.UUID;
@Service public class StorageService {private final Path root;public StorageService(@Value("${evidencias.dir}")String dir){root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(Exception e){throw new IllegalStateException("No se pudo preparar almacenamiento de evidencias",e);}}public String guardar(MultipartFile f){if(f==null||f.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Archivo vacío");String type=f.getContentType();if(type==null||!type.matches("image/(jpeg|png|webp)"))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Solo se permiten imágenes JPEG, PNG o WEBP");String ext=switch(type){case "image/jpeg"->".jpg";case "image/png"->".png";default->".webp";};String name=UUID.randomUUID()+ext;try{Path dst=root.resolve(name).normalize();if(!dst.startsWith(root))throw new SecurityException("Ruta inválida");Files.copy(f.getInputStream(),dst,StandardCopyOption.REPLACE_EXISTING);return name;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"No se pudo guardar la evidencia");}}public Path resolver(String name){if(name==null||!name.matches("[a-f0-9-]{36}\\.(jpg|png|webp)"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nombre de evidencia inválido");Path p=root.resolve(name).normalize();if(!p.startsWith(root)||!Files.isRegularFile(p))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Evidencia no encontrada");return p;}}
